SELECT STCD, IDTM, STTDRCD, HTZ, LTZ, MXQ, MNQ, HTZTM, LTZTM, MXQTM, MNQTM
FROM ST_RVEVS_R
WHERE STTDRCD = #{sttdrcd}

    AND STCD IN

        #{stcd}


ORDER BY IDTM DESC

SELECT STCD, IDTM, STTDRCD, HTZ, LTZ, MXQ, MNQ, HTZTM, LTZTM, MXQTM, MNQTM
FROM ST_RVEVS_R
WHERE STTDRCD = #{sttdrcd}
AND IDTM >= #{stime}
AND IDTM <= #{etime}

    AND STCD IN

        #{stcd}


ORDER BY IDTM DESC

SELECT STCD, IDTM, STTDRCD, HTZ, LTZ, MXQ, MNQ, HTZTM, LTZTM, MXQTM, MNQTM
FROM ST_RVEVS_R
WHERE IDTM >= #{stime}
AND IDTM <= #{etime}
ORDER BY STCD, IDTM DESC

SELECT STCD, IDTM, STTDRCD, HTZ, LTZ, MXQ, MNQ, HTZTM, LTZTM, MXQTM, MNQTM
FROM ST_RVEVS_R
WHERE STCD = #{stcd}
AND IDTM = #{idtm}
AND STTDRCD = #{sttdrcd}

mapper.insert:
MERGE INTO ST_RVEVS_R t USING (
SELECT #{pojo.STCD, jdbcType=VARCHAR} AS STCD, #{pojo.IDTM, jdbcType=VARCHAR} AS IDTM, #{pojo.STTDRCD, jdbcType=VARCHAR} AS STTDRCD, #{pojo.HTZ, jdbcType=DOUBLE} AS HTZ, #{pojo.LTZ, jdbcType=DOUBLE} AS LTZ, #{pojo.MXQ, jdbcType=DOUBLE} AS MXQ, #{pojo.MNQ, jdbcType=DOUBLE} AS MNQ, #{pojo.HTZTM, jdbcType=VARCHAR} AS HTZTM, #{pojo.LTZTM, jdbcType=VARCHAR} AS LTZTM, #{pojo.MXQTM, jdbcType=VARCHAR} AS MXQTM, #{pojo.MNQTM, jdbcType=VARCHAR} AS MNQTM FROM DUAL
) s ON (t.STCD = s.STCD AND t.IDTM = s.IDTM AND t.STTDRCD = s.STTDRCD) WHEN MATCHED THEN UPDATE SET HTZ = s.HTZ, HTZTM = s.HTZTM, LTZ = s.LTZ, LTZTM = s.LTZTM, MXQ = s.MXQ, MXQTM = s.MXQTM, MNQ = s.MNQ, MNQTM = s.MNQTM WHEN NOT MATCHED THEN INSERT (STCD, IDTM, STTDRCD, HTZ, HTZTM, LTZ, LTZTM, MXQ, MXQTM, MNQ, MNQTM) VALUES (s.STCD, s.IDTM, s.STTDRCD, s.HTZ, s.HTZTM, s.LTZ, s.LTZTM, s.MXQ, s.MXQTM, s.MNQ, s.MNQTM)
